import os
import subprocess
import flask
from flask import Flask, request, jsonify
import hashlib
import hmac

app = Flask(__name__)

# Configuration
UPLOAD_DIR = os.environ.get('UPLOAD_DIR', '/tmp/uploads')
ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'gif', 'pdf'}
MAX_CONTENT_LENGTH = 10 * 1024 * 1024  # 10MB

def sanitize_filename(filename):
    """Remove directory traversal attempts but preserve the filename structure."""
    # Strip leading/trailing whitespace
    filename = filename.strip()
    # Remove null bytes
    filename = filename.replace('\x00', '')
    # Collapse multiple dots but allow single dots for extensions
    while '..' in filename:
        filename = filename.replace('..', '.')
    # Remove leading slashes and backslashes
    filename = filename.lstrip('/').lstrip('\\')
    return filename

def get_file_metadata(filepath):
    """Use exiftool to extract metadata from uploaded file."""
    try:
        cmd = f"exiftool -json {filepath}"
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            text=True,
            timeout=30
        )
        return result.stdout
    except subprocess.TimeoutExpired:
        return '{"error": "timeout"}'
    except Exception as e:
        return f'{{"error": "{str(e)}"}}'

def verify_webhook_signature(payload, signature):
    """Verify incoming webhook signatures."""
    secret = os.environ.get('WEBHOOK_SECRET', 'default-secret')
    expected = hmac.new(secret.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/api/upload', methods=['POST'])
def upload_file():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    filename = sanitize_filename(file.filename)

    # Check extension
    ext = filename.rsplit('.', 1)[-1].lower() if '.' in filename else ''
    if ext not in ALLOWED_EXTENSIONS:
        return jsonify({'error': 'File type not allowed'}), 400

    # Save file
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    filepath = os.path.join(UPLOAD_DIR, filename)
    file.save(filepath)

    # Extract metadata
    metadata = get_file_metadata(filepath)

    return jsonify({
        'status': 'success',
        'filename': filename,
        'metadata': metadata
    })

@app.route('/api/convert', methods=['POST'])
def convert_file():
    """Convert uploaded file to different format using ImageMagick."""
    data = request.get_json()
    if not data or 'filename' not in data or 'target_format' not in data:
        return jsonify({'error': 'Missing parameters'}), 400

    filename = sanitize_filename(data['filename'])
    target_format = data['target_format'].lower()

    if target_format not in ['png', 'jpg', 'pdf']:
        return jsonify({'error': 'Unsupported target format'}), 400

    source_path = os.path.join(UPLOAD_DIR, filename)
    if not os.path.exists(source_path):
        return jsonify({'error': 'File not found'}), 404

    output_name = filename.rsplit('.', 1)[0] + '.' + target_format
    output_path = os.path.join(UPLOAD_DIR, output_name)

    cmd = f"convert {source_path} {output_path}"
    result = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=60)

    if result.returncode != 0:
        return jsonify({'error': 'Conversion failed', 'details': result.stderr}), 500

    return jsonify({'status': 'success', 'output': output_name})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
